from typing import List, Optional
import re

from taf.ul.sc.perf.devices.ue.generic_rtg_cus import GenericRtgCus
from taf.ul.sc.rtg import Executor  # type: ignore
from taf.ul.sc.rtg import Workstation  # type: ignore
from taf.ul.sc.rtg import Controller  # type: ignore


class RTG(GenericRtgCus):
    def __init__(self,
                 executor: Optional[Executor] = None,
                 workstation: Optional[Workstation] = None,
                 controllers: Optional[List[Controller]] = None,
                 ):
        super(RTG, self).__init__(executor=executor, workstation=workstation, controllers=controllers)

    def get_used_rrhs(self):
        rrh_types = {}
        if 'radio' in self.executor.config:
            for index in self.executor.config['radio']:
                rrh_types[index] = self.executor.config['radio'][index]['rmod_type']

        if rrh_types:
            used_rrh_types = self.update_used_rrh_types(rrh_types)
            return used_rrh_types
        else:
            return []

    def update_used_rrh_types(self, rrh_types):
        used_rrh_types = []
        for index in self.executor.config['sector']:
            if 'radio' in self.executor.config['sector'][index]:
                radio_index = self.executor.config['sector'][index]['radio']
                used_rrh_types.append(rrh_types[str(radio_index)])
            elif 'obsai_antennas' in self.executor.config['sector'][index]:
                antennas = self.executor.config['sector'][index]['obsai_antennas']
                antenna = re.search(r'([aA-zZ]+)-\d+:\d+:[aA-zZ]+', antennas)
                used_rrh_types.append(antenna.group(1))
        used_rrh_types = ', '.join(set(used_rrh_types))
        return used_rrh_types
